(()=>{"use strict";const t=document.getElementById("loginDialog"),a=t?.querySelector(".login-card"),s=document.getElementById("loginPassword"),n=document.getElementById("loginPasswordToggle");if(!t||!a||!s||!n)return;t.addEventListener("cancel",e=>e.preventDefault()),n.addEventListener("click",()=>{const e=s.type==="text";s.type=e?"password":"text",n.setAttribute("aria-pressed",String(!e)),n.setAttribute("aria-label",e?"Mostrar senha":"Ocultar senha"),s.focus()});const r=()=>{const e=Math.max(0,a.clientWidth-32),l=Math.min(1,Math.max(.72,e/300));t.style.setProperty("--login-turnstile-scale",String(l))};new ResizeObserver(r).observe(a),r()})();
